import { DispatchRun } from "../domain/notification";
import { AlertPublisher } from "../messaging/eventPublisher";
import { AlertConsumer } from "../notifier/consumerWorker";
import { CustomerRepository } from "../repository/customerRepository";
import { DeliveryLogRepository } from "../repository/deliveryLogRepository";
import { OrderRepository } from "../repository/orderRepository";
import { planNotifications } from "./notificationPlanner";

/** 발송 회차: 미발송 이벤트 → 알림 계획 → 발행(1배치) → 소비·문자 발송 → 회차 기록 */
export class DispatchService {
  private lastRunId = 0;

  constructor(
    private readonly orders: OrderRepository,
    private readonly customers: CustomerRepository,
    private readonly publisher: AlertPublisher,
    private readonly consumer: AlertConsumer,
    private readonly log: DeliveryLogRepository,
  ) {}

  runOnce(): DispatchRun {
    const runId = ++this.lastRunId;
    const events = this.orders.takePending();
    const plan = planNotifications(events, this.customers);
    const pub = this.publisher.publishRun(plan.notifications);
    const drained = this.consumer.drain(runId);
    const run: DispatchRun = {
      runId,
      planned: plan.notifications,
      skippedOptOut: plan.skippedOptOut,
      published: pub.accepted,
      batch: pub.batch,
      delivered: drained.delivered,
      failed: drained.failed,
    };
    this.log.saveRun(run);
    return run;
  }
}
import { Notification } from "../domain/notification";
import { CustomerRepository } from "../repository/customerRepository";
import { PendingEvent } from "../repository/orderRepository";

export interface Plan {
  notifications: Notification[];
  skippedOptOut: number;
}

/**
 * 회차에 실린 주문 이벤트를 고객 알림으로 바꾼다.
 *  - 수신 거부 고객은 제외한다.
 *  - 같은 주문·같은 이벤트가 회차 안에 여러 번 기록됐으면(운영자 재입력 등) 한 번만 알린다.
 *  - 이벤트 기록 순서를 유지한다.
 */
export function planNotifications(events: PendingEvent[], customers: CustomerRepository): Plan {
  const seen = new Set<string>();
  const notifications: Notification[] = [];
  let skippedOptOut = 0;
  for (const e of [...events].sort((a, b) => a.seq - b.seq)) {
    const customer = customers.find(e.customerId);
    if (!customer || !customer.smsOptIn) {
      skippedOptOut++;
      continue;
    }
    const id = `${e.orderNo}#${e.kind}`;
    if (seen.has(id)) continue;
    seen.add(id);
    notifications.push({ orderNo: e.orderNo, customerId: e.customerId, kind: e.kind });
  }
  return { notifications, skippedOptOut };
}
import { OrderEventKind } from "./order";

/** 고객에게 보낼 알림 1건 */
export interface Notification {
  orderNo: string;
  customerId: string;
  kind: OrderEventKind;
}

/** 발송 회차 결과 */
export interface DispatchRun {
  runId: number;
  planned: Notification[];
  skippedOptOut: number;
  published: number;
  batch: number;
  delivered: DeliveredAlert[];
  failed: { orderNo: string; kind: OrderEventKind; reason: string }[];
}

export interface DeliveredAlert {
  runId: number;
  orderNo: string;
  customerId: string;
  kind: OrderEventKind;
  phone: string;
  receiptId: string;
}

export const KIND_LABEL: Record<OrderEventKind, string> = {
  PAID: "결제 완료",
  SHIPPED: "배송 시작",
  DELIVERED: "배송 완료",
};
export type Channel = "direct" | "market";
export type OrderEventKind = "PAID" | "SHIPPED" | "DELIVERED";

export interface OrderEvent {
  kind: OrderEventKind;
  /** 이벤트 기록 순번(앱 전역 단조 증가) */
  seq: number;
  dispatched: boolean;
}

export interface Order {
  orderNo: string;
  customerId: string;
  channel: Channel;
  partner?: string;
  placedOn: string; // YYYY-MM-DD
  events: OrderEvent[];
}

export const EVENT_KINDS: readonly OrderEventKind[] = ["PAID", "SHIPPED", "DELIVERED"];

export function isEventKind(v: unknown): v is OrderEventKind {
  return typeof v === "string" && (EVENT_KINDS as readonly string[]).includes(v);
}

/** 2026-10-07 → 261007 */
export function compactDate(placedOn: string): string {
  const m = /^20(\d{2})-(\d{2})-(\d{2})$/.exec(placedOn);
  if (!m) throw new Error("invalid placedOn");
  return `${m[1]}${m[2]}${m[3]}`;
}

/**
 * 주문번호 체계
 *   자사몰:     O<yymmdd>-<일련 5자리>            예) O261007-00042
 *   오픈마켓:   M-<제휴사 4자>-<yymmdd>-<일련 6자리> 예) M-GMKT-261007-000123
 */
export function formatOrderNo(channel: Channel, placedOn: string, seq: number, partner?: string): string {
  const d = compactDate(placedOn);
  if (channel === "direct") return `O${d}-${String(seq).padStart(5, "0")}`;
  if (!partner || !/^[A-Z]{4}$/.test(partner)) throw new Error("invalid partner");
  return `M-${partner}-${d}-${String(seq).padStart(6, "0")}`;
}

