import { createHash } from "crypto";
import { OrderEventKind } from "../domain/order";

const KIND_CODE: Record<OrderEventKind, string> = {
  PAID: "paid",
  SHIPPED: "ship",
  DELIVERED: "dlvd",
};

/**
 * mqpub 3.4.1은 한 배치 안에서 키의 앞 16바이트가 같으면 첫 메시지만 저장하고 나머지는 버린다.
 * 그래서 앞 16바이트 안에 메시지마다 다른 값(논리 키의 결정적 해시 7자)을 둔다.
 */
export const DEDUP_WINDOW = 16;

/**
 * 알림 메시지 키 — `<네임스페이스>.<이벤트>.<해시 7자>:<업무 식별자>`.
 * 해시는 논리 키에서 결정적으로 만들어 재발행 시에도 같은 키가 나온다.
 * 소비 측은 이 키로 이미 처리한 메시지를 걸러낸다(재전달 대비).
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const prefix = `${namespace}.${KIND_CODE[kind]}.`;
  const digest = createHash("sha256").update(`${prefix}${orderNo}`).digest("hex").slice(0, 16);
  const tag = (BigInt(`0x${digest}`) % 36n ** 7n).toString(36).padStart(7, "0");
  return `${prefix}${tag}:${orderNo}`;
}

