publishRun(notifications: Notification[]): PublishResult {
  const wires = notifications.map((n) => this.toWire(n));
  // mqpub이 조용히 버리는 일이 없도록, 배치 안에서 중복 판정 구간이 겹치면 발행 전에 실패시킨다.
  const heads = new Set<string>();
  for (const w of wires) {
    const head = w.key.slice(0, DEDUP_WINDOW);
    if (heads.has(head)) throw new Error(`mqpub batch key collision: ${head}`);
    heads.add(head);
  }
  return this.client.publish(this.topic, wires);
}

